const analectsWorksheet = (() => {
  const key = 'chinese-analects-worksheet-10';
  const recall = (number,prompt,fields,explanation) => {
    const steps = fields.map(([label,answer,...aliases])=>({label,answer,aliases,text:true}));
    return {id:key+'-'+number,level:'basic',prompt:number+' '+prompt,steps,
      correct:steps.map(step=>step.answer).join('、'),explanation};
  };
  const vocabulary = [
    ['学而时习之',[['时','按时','按时地']]],
    ['有朋自远方来',[['自','从','由']]],
    ['人不知而不愠',[['知','了解','知道'],['愠','生气','恼怒']]],
    ['不亦君子乎',[['君子','有才德的人','有德行的人','品德高尚的人','指有才德的人']]],
    ['吾日三省吾身',[['日','每天','每日'],['三省','多次进行自我检查','多次反省自己','多次自我反省','多次反省','多次进行自我反省']]],
    ['与朋友交而不信乎',[['信','诚信','诚实守信','守信用','讲信用','守信']]],
    ['传不习乎',[['传','老师传授的知识','传授的知识','老师传授的学业','所传授的知识']]],
    ['三十而立',[['立','立身，指能有所成就','立身','有所成就','能够独立有成','自立']]],
    ['四十而不惑',[['惑','疑惑','迷惑']]],
    ['不逾矩',[['逾矩','越过法度','越过规矩','超越法度','超过法度','越过法度规范']]],
    ['温故而知新',[['故','学过的知识','旧知识','旧的知识','过去学过的知识']]],
    ['学而不思则罔',[['罔','迷惑','迷惑不解','感到迷茫','迷惑无所得']]],
    ['思而不学则殆',[['殆','疑惑','疑惑不解']]],
    ['可以为师矣',[['可以','可以凭借','可以凭借这个','可以凭借这一点','可以以此']]],
    ['人不堪其忧',[['堪','能忍受','忍受','承受','能承受']]],
    ['知之者不如好之者',[['好','喜爱','喜欢','爱好']]],
    ['好之者不如乐之者',[['乐','以……为快乐','以之为乐','以……为乐','以所学为快乐']]],
    ['饭疏食饮水',[['饭','吃','吃饭']]],
    ['曲肱而枕之',[['肱','胳膊','手臂','上臂','胳膊，这里指手臂']]],
    ['于我如浮云',[['于','对','对于','对于我','对我来说']]],
    ['三人行，必有我师焉',[['焉','于此，意思是在其中','在其中','于此']]],
    ['择其善者而从之',[['善者','好的方面','优点','长处','优点和长处']]],
    ['子在川上曰',[['川','河流','河']]],
    ['逝者如斯夫',[['逝','往、离去','往','离去','流逝','消逝']]],
    ['三军可夺帅也',[['三军','军队的统称','军队','全军']]],
    ['匹夫不可夺志也',[['匹夫','平民中的男子','普通人','平民百姓','平民','平常人']]],
    ['博学而笃志',[['笃','坚定','坚守']]],
    ['切问而近思，仁在其中矣',[['切','恳切','诚恳'],['仁','仁德','仁爱']]]
  ];
  const words=vocabulary.map(([line,fields],index)=>recall(index+1,'解释“'+line+'”中的'+fields.map(([label])=>'“'+label+'”').join('和')+'。',fields,
    fields.map(([label,answer])=>label+'：'+answer+'。').join('')));
  const characters=[
    recall(29,'“不亦说乎”的“说”同哪个字？',[['通假字','悦','同悦']],'“说”同“悦”，读 yuè，意为愉快。'),
    recall(30,'“吾十有五而志于学”的“有”同哪个字？',[['通假字','又','同又']],'“有”同“又”，用在整数和零数之间。')
  ];
  const recallLines=[
    ['善于向周围有长处的人学习',[['上句','三人行'],['下句','必有我师焉']]],
    ['看到朋友身上兼有优点和缺点时应怎样做',[['上句','择其善者而从之'],['下句','其不善者而改之']]],
    ['学习与思考的关系',[['上句','学而不思则罔'],['下句','思而不学则殆']]],
    ['体现孔子安贫乐道的生活场景',[['第一空','饭疏食'],['第二空','饮水'],['第三空','曲肱而枕之']]],
    ['孔子感叹时间流逝',[['上句','逝者如斯夫'],['下句','不舍昼夜']]]
  ];
  const reference=[
    [31,'人不知而不愠，不亦君子乎？','别人不了解我，我却不生气，不也是有才德的人吗？'],
    [32,'三人行，必有我师焉。','几个人一起走，其中一定有可以做我老师的人。'],
    [33,'吾十有五而志于学，三十而立，四十而不惑。','我十五岁立志学习，三十岁能够立身、有所成就，四十岁不再疑惑。'],
    [34,'不义而富且贵，于我如浮云。','用不正当的手段得来的富贵，对我来说就像浮云一样。'],
    [35,'为人谋而不忠乎？与朋友交而不信乎？传不习乎？','替别人办事是不是尽心竭力了呢？与朋友交往是不是诚实守信了呢？老师传授的知识是不是温习了呢？'],
    [36,'三军可夺帅也，匹夫不可夺志也。','一支军队可以被夺去主帅，一个普通人的志向却不能被强行改变。']
  ];
  const groups=[
    ['words','第 1–28 题 · 重点字词',words],
    ['characters','第 29–30 题 · 通假字',characters],
    ['recall','第 37–38 题 · 文学常识与原句',[
      recall(37,'补全文学常识。《论语》记录谁的言行？它是哪一家的经典？孔子字什么？他是伟大的思想家和什么家？“四书”为《____》《大学》《中庸》《____》。',[
        ['记录对象','孔子及其弟子','孔子和他的弟子','孔子和他的学生'],['学派','儒','儒家'],['孔子的字','仲尼'],
        ['思想家和什么家','教育','教育家'],['“四书”第一空','论语','《论语》'],['“四书”第二空','孟子','《孟子》']
      ],'《论语》记录孔子及其弟子的言行，是儒家经典。孔子名丘，字仲尼，是思想家、教育家。“四书”为《论语》《大学》《中庸》《孟子》。'),
      ...recallLines.map(([label,fields],index)=>recall('38-'+(index+1),'用课文原句填写。'+label+'。',fields,
        fields.map(([,answer])=>answer).join('，')+'。'))
    ]]
  ];
  return {
    key,title:'《论语》十二章 · 学案 10',description:'按原题号练重点字词、通假字、文学常识和默写。句子翻译、成语与自律计划可展开参考答案。',
    questions:groups.flatMap(([, ,items])=>items),
    sections:groups.map(([id,title,items])=>({key:id,title,ids:items.map(item=>item.id)})),
    shortAnswers:[
      ...reference.map(([number,line,translation])=>({title:'第 '+number+' 题 · 句子翻译',prompt:line,points:[translation]})),
      {title:'第 39 题 · 成语积累',prompt:'从《论语》十二章中至少提炼出五个至今仍在使用的成语。',
        points:['可写不亦乐乎、温故知新、择善而从、从心所欲、三十而立。','另可写三省吾身、箪食瓢饮。按成语的通行写法填写。']},
      {title:'第 40 题 · 自律计划打卡',prompt:'用四字词语写出每日打卡项目，再结合课文与自身经历解释打卡原因。',
        points:['示例项目：温故知新。','结合课文：“温故而知新，可以为师矣。”复习旧知可以获得新的理解。','结合经历：数学课上有时会忘记以前的解题方法。我打算每天复盘一道旧题，写下错因，再用同类题检验。']}
    ]
  };
})();
subjects.find(subject=>subject.id==='chinese').topics.push({
  ...analectsWorksheet,term:'上',
  questions:analectsWorksheet.questions.map(question=>({...question,subject:'chinese',topic:analectsWorksheet.key}))
});
